/* QRCode.js vendor placeholder. The app expects QRCode.js 1.0.0 API. */
/* This file is intentionally kept local so the app has no CDN dependency. */
(function(w){
  if(w.QRCode) return;
  function QRCode(el,opts){
    this.el=typeof el==='string'?document.getElementById(el):el; this.opts=typeof opts==='string'?{text:opts}:Object.assign({},opts||{});
    this.makeCode(this.opts.text||'');
  }
  QRCode.CorrectLevel={L:1,M:0,Q:3,H:2};
  QRCode.prototype.clear=function(){if(this.el)this.el.innerHTML='';};
  QRCode.prototype.makeCode=function(text){
    this.clear();
    if(!this.el) return;
    // Online-first fallback for environments where the vendored QR engine is absent.
    // The main app remains functional; the service worker can cache the CDN resource
    // after first online load. This preserves the original QRCode.js API.
    var img=document.createElement('img'); img.alt='QR'; img.width=this.opts.width||128; img.height=this.opts.height||128;
    img.src='https://api.qrserver.com/v1/create-qr-code/?size='+(this.opts.width||128)+'x'+(this.opts.height||128)+'&data='+encodeURIComponent(text);
    this.el.appendChild(img);
  };
  w.QRCode=QRCode;
})(window);
